DO $$
DECLARE actor uuid; org bigint; un bigint; oc bigint; parent bigint; child bigint; other_event bigint; group_id bigint; sp bigint; free_slot bigint; booked_slot bigint; related_child bigint;
 result jsonb; payload jsonb; cmd uuid; attendance_cmd uuid; attendance_result jsonb;
BEGIN
 PERFORM public.create_user_for_test('event-teardown','event-teardown@example.invalid');actor:=public.get_user_id('event-teardown');
 INSERT INTO public.organizations(title) VALUES('Event teardown') RETURNING id INTO org;
 UPDATE public.user_info SET organization=org WHERE id=actor;
 INSERT INTO public.units(title,organization) VALUES('Event teardown',org) RETURNING id INTO un;
 INSERT INTO public.occasions(title,organization,unit,link,start_time,end_time,is_open,features) VALUES('Event teardown',org,un,gen_random_uuid()::text,now(),now()+interval '1 day',true,'[{"code":"workshops","is_enabled":true}]') RETURNING id INTO oc;
 INSERT INTO public.occasion_users(occasion,"user",is_editor,is_editor_view,is_approved) VALUES(oc,actor,true,true,true);
 INSERT INTO public.events(occasion,title,start_time,end_time,is_hidden,"order",data) VALUES(oc,'Parent',now()+interval '1 hour',now()+interval '2 hours',false,0,'{}') RETURNING id INTO parent;
 INSERT INTO public.events(occasion,title,start_time,end_time,is_hidden,"order",data) VALUES(oc,'Child',now()+interval '1 hour',now()+interval '2 hours',false,0,'{}') RETURNING id INTO child;
 INSERT INTO public.events(occasion,title,start_time,end_time,is_hidden,"order",data) VALUES(oc,'Other',now()+interval '1 hour',now()+interval '2 hours',false,0,'{}') RETURNING id INTO other_event;
 INSERT INTO public.event_groups(event_parent,event_child) VALUES(parent,child);
 INSERT INTO public.exclusive_groups(occasion,title) VALUES(oc,'Exclusive') RETURNING id INTO group_id;
 INSERT INTO public.exclusive_events("group",event) VALUES(group_id,parent),(group_id,other_event);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);PERFORM set_config('request.jwt.claim.role','authenticated',true);
 payload:=public.get_event_command_data_v1(child);cmd:=gen_random_uuid();
 EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.delete_event_client_sync_v1(oc,parent,cmd,0);ASSERT result->>'status'='applied';ASSERT public.delete_event_client_sync_v1(oc,parent,cmd,0)=result;
 ASSERT public.save_event_client_sync_v1(oc,gen_random_uuid(),0,payload)->>'status'='conflict','parent removal invalidates the original child editor';
 ASSERT public.save_exclusive_group_client_sync_v1(oc,gen_random_uuid(),0,jsonb_build_object('id',group_id,'title','Stale group','events',jsonb_build_array(other_event)))->>'status'='conflict';
 EXECUTE 'RESET ROLE';
 ASSERT (SELECT version=1 FROM public.client_aggregate_versions WHERE aggregate_type='event' AND scope_id=oc AND aggregate_id=child::text);
 ASSERT (SELECT version=1 FROM public.client_aggregate_versions WHERE aggregate_type='exclusive_group' AND scope_id=oc AND aggregate_id=group_id::text);
 payload:=public.get_event_command_data_v1(child)||jsonb_build_object('title','Saved child');
 EXECUTE 'SET LOCAL ROLE authenticated';
 ASSERT public.save_event_client_sync_v1(oc,gen_random_uuid(),1,payload)->>'status'='applied';
 EXECUTE 'RESET ROLE';
 INSERT INTO public.speakers(occasion,title) VALUES(oc,'Speaker') RETURNING id INTO sp;
 EXECUTE 'SET LOCAL ROLE authenticated';
 ASSERT public.set_event_speakers(child,ARRAY[sp])->>'code'='200';
 ASSERT public.save_event_speakers_client_sync_v1(oc,child,gen_random_uuid(),2,'{}')->>'status'='conflict','legacy speaker facade advances event version';
 ASSERT public.delete_speaker_client_sync_v1(oc,sp,gen_random_uuid(),0)->>'status'='applied';
 ASSERT public.save_event_speakers_client_sync_v1(oc,child,gen_random_uuid(),3,'{}')->>'status'='conflict','speaker removal invalidates event selection';
 attendance_cmd:=gen_random_uuid();attendance_result:=public.set_event_attendance_client_sync_v1(child,actor,'sign_in',attendance_cmd);ASSERT attendance_result->>'code'='200';
 ASSERT public.delete_event_client_sync_v1(oc,child,gen_random_uuid(),4)->>'status'='applied';
 ASSERT public.set_event_attendance_client_sync_v1(child,actor,'sign_in',attendance_cmd)=attendance_result,'attendance response survives event deletion';
 EXECUTE 'RESET ROLE';
 INSERT INTO public.speakers(occasion,title) VALUES(oc,'Counselor') RETURNING id INTO sp;
 INSERT INTO public.events(occasion,title,start_time,end_time,data) VALUES(oc,'Free',now()+interval '1 hour',now()+interval '2 hours','{"is_counseling_slot":true}') RETURNING id INTO free_slot;
 INSERT INTO public.events(occasion,title,start_time,end_time,data) VALUES(oc,'Booked',now()+interval '1 hour',now()+interval '2 hours','{"is_counseling_slot":true}') RETURNING id INTO booked_slot;
 INSERT INTO public.events(occasion,title,start_time,end_time) VALUES(oc,'Related child',now()+interval '1 hour',now()+interval '2 hours') RETURNING id INTO related_child;
 INSERT INTO public.event_speakers(event,speaker) VALUES(free_slot,sp),(booked_slot,sp);
 INSERT INTO public.event_groups(event_parent,event_child) VALUES(free_slot,related_child);
 INSERT INTO public.exclusive_events("group",event) VALUES(group_id,free_slot);
 INSERT INTO public.event_users(event,"user") VALUES(booked_slot,actor);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version) VALUES('event','occasion',oc,booked_slot::text,5);
 cmd:=gen_random_uuid();EXECUTE 'SET LOCAL ROLE authenticated';
 result:=public.delete_empty_counseling_slots_client_sync_v1(sp,NULL,cmd);ASSERT result->>'status'='applied';ASSERT result#>>'{data,deleted}'='1';
 ASSERT public.delete_empty_counseling_slots_client_sync_v1(sp,NULL,cmd)=result;
 EXECUTE 'RESET ROLE';
 ASSERT NOT EXISTS(SELECT 1 FROM public.events WHERE id=free_slot);ASSERT EXISTS(SELECT 1 FROM public.events WHERE id=booked_slot);
 ASSERT (SELECT version=5 FROM public.client_aggregate_versions WHERE aggregate_type='event' AND scope_id=oc AND aggregate_id=booked_slot::text);
 ASSERT (SELECT version=1 FROM public.client_aggregate_versions WHERE aggregate_type='event' AND scope_id=oc AND aggregate_id=related_child::text);
 ASSERT (SELECT version=2 FROM public.client_aggregate_versions WHERE aggregate_type='exclusive_group' AND scope_id=oc AND aggregate_id=group_id::text);
 ASSERT NOT has_table_privilege('authenticated','public.event_speakers','INSERT');
 ASSERT NOT has_table_privilege('authenticated','public.event_users','INSERT');
 ASSERT NOT has_function_privilege('authenticated','public.delete_events_domain_internal_v1(bigint,bigint[])','EXECUTE');
END $$;
